/* حامل مشهد كسول بارتفاع ثابت — يمنع قفزة التخطيط عند وصول الحزمة.
   ★ جولة 2: لا يُركَّب المشهد (ولا تُنزَّل حزمته three.js) إلا عند اقتراب
   القسم من الشاشة (900px). قبل الجولة 2 كان React.lazy يجلب الحزمة فور
   تركيب الرئيسية رغم أن المشاهد تحت الطيّ — وهذا ما أبقى chunk 408
   (143KB) في التحميل الأولي. في بيئة الاختبار يُركَّب فوراً (بلا IO).
   ★ جولة 7: بوابة التمرير — IO بهامش 900px قد يُطلق والمستخدم أعلى
   الصفحة (والمختبر لا يتمرر أبداً)، وتركيب المشهد حينها يعني تنزيل
   three.js وتنفيذها (~600ms خيط رئيسي) وسط نافذة LCP/TBT. إن كان
   المستخدم مرّر فعلاً يُركَّب فوراً، وإلا ننتظر أول تمرير (مع حدّ
   10s احتياطاً للقارئ الثابت) بدل التحميل أثناء أول رسم. */
function SceneSlot(props) {
  const ref = useRef(null);
  const testEnv = (typeof process !== "undefined" && process.env && process.env.NODE_ENV === "test");
  const [near, setNear] = useState(testEnv);
  useEffect(
    function () {
      if (near) return undefined;
      const el = ref.current;
      if (!el) return undefined;
      if (typeof window === "undefined" || typeof window.IntersectionObserver !== "function") {
        setNear(true);
        return undefined;
      }
      let alive = true;
      let io = null;
      let timer = 0;
      function cleanup() {
        alive = false;
        try { if (io) io.disconnect(); } catch (e) {}
        try { if (timer) window.clearTimeout(timer); } catch (e) {}
        try { window.removeEventListener("scroll", onMount); } catch (e) {}
        try {
          ["wheel", "touchstart", "pointerdown", "keydown"].forEach(function (ev) {
            window.removeEventListener(ev, onMount);
          });
        } catch (e) {}
      }
      function mount() {
        if (!alive) return;
        cleanup();
        setNear(true);
      }
      /* ★ إصلاح الخلل: كان التركيب مشروطاً بالتمرير (scrollY>40) حتى لو
         كان القسم على بُعد 900px من الشاشة — فيثبّت اللودر ويُضاعف التأخير
         مع البوابة الداخلية للمشهد، فتنفد مهلة الـ30 ثانية قبل بدء التنزيل.
         الآن: الاقتراب من الشاشة (IO) يُركّب فوراً بلا شرط تمرير، مع شبكة
         أمان (أي تمرير/تفاعل + مهلة قصوى) حتى لا يبقى القسم فارغاً أبداً
         إن لم يُطلق IO (تبويب مخفي، حاوية تمرير غريبة، متصفح قديم). */
      function onMount() {
        mount();
      }
      try {
        window.addEventListener("scroll", onMount, { passive: true });
      } catch (e2) {
        try { window.addEventListener("scroll", onMount); } catch (e3) {}
      }
      try {
        ["wheel", "touchstart", "pointerdown", "keydown"].forEach(function (ev) {
          try { window.addEventListener(ev, onMount, { passive: true }); }
          catch (e4) { try { window.addEventListener(ev, onMount); } catch (e5) {} }
        });
      } catch (e) {}
      try {
        if (timer) window.clearTimeout(timer);
        timer = window.setTimeout(function () { mount(); }, 12000);
      } catch (e) {}
      try {
        io = new window.IntersectionObserver(
          function (entries) {
            if (!alive) return;
            for (let i = 0; i < entries.length; i++) {
              if (entries[i].isIntersecting) {
                try { io.disconnect(); } catch (e) {}
                mount();
                return;
              }
            }
          },
          { rootMargin: "900px 0px" }
        );
        io.observe(el);
        return cleanup;
      } catch (e) {
        setNear(true);
        return undefined;
      }
    },
    [near]
  );
  const placeholder = (
    <div
      className="scene-slot-fallback"
      aria-busy={near ? "true" : undefined}
      style={{ minHeight: "420px" }}
    />
  );
  return (
    <div ref={ref}>
      {near ? (
        <Suspense fallback={placeholder}>{props.children}</Suspense>
      ) : placeholder}
    </div>
  );
}

