/* ============================================================
   أطياب الجاسم (React) — أنيميشن الوجو (LogoAnimation)

   الجزء البصري في يسار الصفحة الرئيسية عند فتح الموقع: الوجو/الكرة
   الذهبية مع ثلاث حلقات مدارية، وشعار أطياب في المنتصف، وخمس بطاقات
   عائمة تظهر بالتتابع.

   ★ ماذا يتحرّك؟ الحلقات تدور (CSS: spinSlow) والكرة تصعد وتهبط
     (orbFloat) والبطاقات تطفو (floaty)، وهذا المكوّن يضيف:
       1) دخول متتابع للبطاقات بعد التركيب (stagger).
       2) إمالة خفيفة تتبع مؤشّر الفأرة (parallax) على سطح المكتب فقط،
          مُعطَّلة عند تفضيل تقليل الحركة وعند أجهزة اللمس.
   ★ لا يقرأ شيئاً من Redux — مكوّن بصري صرف، وتُمرَّر إليه خصائص
     اختيارية (labels · src · className) عند الحاجة.
   ============================================================ */

import { useEffect, useRef, useState } from "react";
import { LogoMark } from "../Source/Icons.jsx";

const DEFAULT_CARDS = ["عطور شرقية أصيلة", "عود معتّق فاخر", "توصيل لكل الإمارات", "ضمان الأصالة", "تغليف هدايا فاخر"];

function prefersReducedMotion() {
  try {
    return !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  } catch (e) {
    return false;
  }
}

function isTouch() {
  try {
    return !!(window.matchMedia && window.matchMedia("(hover: none)").matches);
  } catch (e) {
    return false;
  }
}

export default function LogoAnimation(props) {
  const cards = props.cards || DEFAULT_CARDS;
  const orbSrc = props.orbSrc || (process.env.PUBLIC_URL || "") + "/home/hero-orb.png";
  const orbWebp = props.orbWebp || (process.env.PUBLIC_URL || "") + "/home/hero-orb.webp";
  const orbAlt = props.orbAlt || "تشكيلة عطور أطياب الجاسم: منايا، جساس، بلو كليكات، وكليكات";
  const showBrand = props.brand !== false;
  const plainCls = props.plain ? " hero-orb--plain" : "";
  const orbitRef = useRef(null);
  const frameRef = useRef(0);
  const [entered, setEntered] = useState(false);

  /* دخول متتابع: نُشغّل الحالة بعد أول إطار حتى تبدأ الانتقالات فعلاً */
  useEffect(
    function () {
      const id = window.setTimeout(function () {
        setEntered(true);
      }, 60);
      return function () {
        window.clearTimeout(id);
      };
    },
    []
  );

  /* إمالة خفيفة تتبع المؤشّر — rAF واحد لكل حركة، وبلا أي كتابة عند التوقف */
  useEffect(
    function () {
      const el = orbitRef.current;
      /* parallax مُعطَّل عند اللمس أو عند تفضيل تقليل الحركة */
      if (!el || props.parallax === false || prefersReducedMotion() || isTouch()) return undefined;

      function onMove(e) {
        if (frameRef.current) return;
        frameRef.current = window.requestAnimationFrame(function () {
          frameRef.current = 0;
          const rect = el.getBoundingClientRect();
          if (!rect.width || !rect.height) return;
          const dx = (e.clientX - (rect.left + rect.width / 2)) / rect.width;
          const dy = (e.clientY - (rect.top + rect.height / 2)) / rect.height;
          el.style.setProperty("--pa-tilt-y", (dx * 7).toFixed(2) + "deg");
          el.style.setProperty("--pa-tilt-x", (-dy * 7).toFixed(2) + "deg");
        });
      }
      function onLeave() {
        if (frameRef.current) {
          window.cancelAnimationFrame(frameRef.current);
          frameRef.current = 0;
        }
        el.style.setProperty("--pa-tilt-y", "0deg");
        el.style.setProperty("--pa-tilt-x", "0deg");
      }

      el.addEventListener("pointermove", onMove);
      el.addEventListener("pointerleave", onLeave);
      return function () {
        el.removeEventListener("pointermove", onMove);
        el.removeEventListener("pointerleave", onLeave);
        onLeave();
      };
    },
    [props.parallax]
  );

  return (
    <div className="hero-visual">
      <div className={"orbit pa-logo" + (entered ? " is-in" : "")} ref={orbitRef}>
        <span className="orbit-ring" />
        <span className="orbit-ring" />
        <span className="orbit-ring" />

        <figure className={"hero-orb" + plainCls}>
          <picture className="orb-day">
            <source srcSet={orbWebp} type="image/webp" />
            <img
              width="480"
              height="480"
              decoding="async"
              fetchPriority="high"
              src={orbSrc}
              srcSet={props.orbSrcSet || undefined}
              sizes="(max-width: 700px) 75vw, 420px"
              alt={orbAlt}
            />
          </picture>
          {props.orbNightSrc ? (
          <picture className="orb-night">
            {props.orbNightWebp ? (<source srcSet={props.orbNightWebp} type="image/webp" />) : null}
            <img
              width="480"
              height="480"
              decoding="async"
              src={props.orbNightSrc}
              alt={orbAlt}
            />
          </picture>
          ) : null}
        </figure>

        {showBrand ? (
        <span className="pa-brand" aria-hidden="true">
          <LogoMark />
          <b>أطياب الجاسم</b>
          <small>ATYAB AL-JASEM</small>
        </span>
        ) : null}

        {cards.map(function (label, i) {
          return (
            <span
              className={"float-card fc-" + (i + 1) + " pa-card"}
              key={label}
              style={{ "--pa-i": i }}
            >
              <i />
              {label}
            </span>
          );
        })}
      </div>
    </div>
  );
}
